-- Game configuration for BedWars
local Config = {
	-- Team settings
	Teams = {
		{
			Name = "Red",
			Color = Color3.fromRGB(255, 0, 0),
			SpawnIsland = "RedIsland",
		},
		{
			Name = "Blue",
			Color = Color3.fromRGB(0, 0, 255),
			SpawnIsland = "BlueIsland",
		},
		{
			Name = "Green",
			Color = Color3.fromRGB(0, 255, 0),
			SpawnIsland = "GreenIsland",
		},
		{
			Name = "Yellow",
			Color = Color3.fromRGB(255, 255, 0),
			SpawnIsland = "YellowIsland",
		},
	},
	-- Resource generator settings
	Generators = {
		Iron = {
			RatePerSecond = 1,
			Capacity = 10,
		},
		Gold = {
			RatePerSecond = 0.5,
			Capacity = 10,
		},
		Emerald = {
			RatePerSecond = 0.2,
			Capacity = 5,
		},
	},
	-- Block settings
	Block = {
		GridSize = 4, -- studs
	},
	-- Shop prices
	Shop = {
		Blocks = {
			Stone = 10,
			Wool = 5,
			Obsidian = 20,
		},
		Weapons = {
			Sword = 15,
		},
		Armor = {
			Helmet = 20,
			Chestplate = 30,
			Leggings = 25,
			Boots = 15,
		},
		Tools = {
			Pickaxe = 12,
			Shovel = 10,
		},
	},
	-- Match settings
	Match = {
		MinPlayers = 8,
		MaxPlayers = 16,
		RoundTime = 300, -- seconds
	},
}
return Config

